    protected void createJournalLine(Common _purchLine)
    {
        PurchLine       purchLine = _purchLine as PurchLine;
        METPurchLine    metPurchLine;
        PurchLineAllVersions    purchLineAllVersions;

        next createJournalLine(_purchLine);

        select count(RecId) from purchLineAllVersions
            where   purchLineAllVersions.PurchId        == purchLine.PurchId &&
                    purchLineAllVersions.InventTransId  == purchLine.InventTransId &&
                    purchLineAllVersions.IsArchived     == NoYes::No;

        if(purchLineAllVersions.RecId == 1)
        {
            metPurchLine = purchLine.metPurchLine();

            if(metPurchLine)
            {
                metPurchLine.selectForUpdate(true);

                metPurchLine.Weight = METWHSPhysDimUOMSite::convertWeight(purchLine.ItemId, 1, purchLine.PurchUnit, purchLine.inventDim());
                metPurchLine.Volume = METWHSPhysDimUOMSite::convertVolume(purchLine.ItemId, 1, purchLine.PurchUnit, purchLine.inventDim());

                metPurchLine.update();
            }
        }
    }
